/* ================= 双模型推理 (与 ml/score_dual.py fp32 参照对齐) ================= */

static float relu_f(float x) { return x > 0.0f ? x : 0.0f; }

/* 表格 MLP: x[28] 标准化 -> 256 -> 128 -> 1 */
float ml_tab_p(const double x[28])
{
    static float h1[256], h2[128];
    int i, j;
    for (j = 0; j < 256; j++) {
        float s = TAB_B1[j];
        for (i = 0; i < 28; i++)
            s += TAB_W1[j * 28 + i] * ((float)x[i] - TAB_MEANS[i]) / TAB_STDS[i];
        h1[j] = relu_f(s);
    }
    for (j = 0; j < 128; j++) {
        float s = TAB_B2[j];
        for (i = 0; i < 256; i++) s += TAB_W2[j * 256 + i] * h1[i];
        h2[j] = relu_f(s);
    }
    {
        float z = TAB_B3;
        for (i = 0; i < 128; i++) z += TAB_W3[i] * h2[i];
        if (z > 50.0f) z = 50.0f; if (z < -50.0f) z = -50.0f;
        return 1.0f / (1.0f + expf(-z));
    }
}

/* delta/head 编码: 前 3072 字节 -> 相邻字节差分 (mod 256) */
int ml_delta_img(const char *path, unsigned char out[3072])
{
    FILE *f = fopen(path, "rb");
    int got = 0, i;
    unsigned char raw[3072];
    if (!f) return 0;
    got = (int)fread(raw, 1, sizeof raw, f);
    fclose(f);
    if (got <= 0) return 0;
    if (got < 3072) memset(raw + got, 0, 3072 - got);
    out[0] = raw[0];
    for (i = 1; i < 3072; i++) out[i] = (unsigned char)(raw[i] - raw[i - 1]);
    return 1;
}

static void conv3x3(const float *inp, int h, int w, int cin, int cout,
                    const float *wm, const float *bm, float *out)
{
    int co, y, x, ci, ky, kx;
    for (co = 0; co < cout; co++)
        for (y = 0; y < h; y++)
            for (x = 0; x < w; x++) {
                float s = bm[co];
                for (ci = 0; ci < cin; ci++)
                    for (ky = 0; ky < 3; ky++) {
                        int yy = y + ky - 1;
                        if (yy < 0 || yy >= h) continue;
                        for (kx = 0; kx < 3; kx++) {
                            int xx = x + kx - 1;
                            if (xx < 0 || xx >= w) continue;
                            s += wm[((co * cin + ci) * 9) + (ky * 3 + kx)]
                               * inp[ci * h * w + yy * w + xx];
                        }
                    }
                out[co * h * w + y * w + x] = s;
            }
}

static void maxpool2(const float *inp, int h, int w, int c, float *out)
{
    int cc, y, x;
    for (cc = 0; cc < c; cc++)
        for (y = 0; y < h / 2; y++)
            for (x = 0; x < w / 2; x++) {
                float a = inp[cc * h * w + (y * 2) * w + x * 2];
                float b = inp[cc * h * w + (y * 2) * w + x * 2 + 1];
                float d = inp[cc * h * w + (y * 2 + 1) * w + x * 2];
                float e = inp[cc * h * w + (y * 2 + 1) * w + x * 2 + 1];
                float m1 = a > b ? a : b, m2 = d > e ? d : e;
                out[cc * (h / 2) * (w / 2) + y * (w / 2) + x] = m1 > m2 ? m1 : m2;
            }
}

/* 图像 CNN: 32×32×3 delta 图 */
float ml_img_p(const unsigned char img[3072])
{
    static float in32[3072], c1[16 * 32 * 32], p1[16 * 16 * 16], c2[32 * 16 * 16],
                 p2[32 * 8 * 8], c3[64 * 8 * 8], flat8[4096], h[128];
    int i, j, c, oy, ox;
    for (i = 0; i < 3072; i++)
        in32[(i % 3) * 1024 + i / 3] = ((float)img[i] - IMG_MEAN) / IMG_STD;
    conv3x3(in32, 32, 32, 3, 16, IMG_C1W, IMG_C1B, c1);
    for (i = 0; i < 16 * 32 * 32; i++) c1[i] = relu_f(c1[i]);
    maxpool2(c1, 32, 32, 16, p1);
    conv3x3(p1, 16, 16, 16, 32, IMG_C2W, IMG_C2B, c2);
    for (i = 0; i < 32 * 16 * 16; i++) c2[i] = relu_f(c2[i]);
    maxpool2(c2, 16, 16, 32, p2);
    conv3x3(p2, 8, 8, 32, 64, IMG_C3W, IMG_C3B, c3);
    for (i = 0; i < 64 * 8 * 8; i++) c3[i] = relu_f(c3[i]);
    /* pool2 -> 4×4, adaptive-pool(8) 平铺 2×2 */
    for (c = 0; c < 64; c++)
        for (oy = 0; oy < 8; oy++)
            for (ox = 0; ox < 8; ox++) {
                int ay = oy / 2, ax = ox / 2;
                float a = c3[c * 64 + ay * 2 * 8 + ax * 2];
                float b = c3[c * 64 + ay * 2 * 8 + ax * 2 + 1];
                float d = c3[c * 64 + (ay * 2 + 1) * 8 + ax * 2];
                float e = c3[c * 64 + (ay * 2 + 1) * 8 + ax * 2 + 1];
                float m1 = a > b ? a : b, m2 = d > e ? d : e;
                flat8[c * 64 + oy * 8 + ox] = m1 > m2 ? m1 : m2;
            }
    for (j = 0; j < 128; j++) {
        float s = IMG_F1B[j];
        for (i = 0; i < 4096; i++) s += IMG_F1W[j * 4096 + i] * flat8[i];
        h[j] = relu_f(s);
    }
    {
        float z = IMG_F2B;
        for (i = 0; i < 128; i++) z += IMG_F2W[i] * h[i];
        if (z > 50.0f) z = 50.0f; if (z < -50.0f) z = -50.0f;
        return 1.0f / (1.0f + expf(-z));
    }
}

/* 灵敏度判定: 0=高检测 1=平衡 2=低误杀 (阈值 2026-09-25 折外标定) */
MlVerdict ml_verdict(float tab, float img, int mode)
{
    MlVerdict v;
    switch (mode) {
    case 0: { float s = 0.2f * tab + 0.3f * img; v.score = s; v.high = s > 0.1992f; break; }
    case 2: v.score = tab < img ? tab : img; v.high = tab > 0.20f && img > 0.85f; break;
    default: v.score = tab < img ? tab : img; v.high = tab > 0.40f && img > 0.25f; break;
    }
    return v;
}

float ml_tab_threshold(int mode)
{
    return mode == 0 ? 0.60f : (mode == 2 ? 0.85f : 0.70f);
}
